INSERT INTO translations (lang, source, value) VALUES ('en', 'தமிழ்நாடு தவ்ஹீத் ஜமாஅத் - கொள்கை', 'Tamil Nadu Thowheed Jamath: our creed') ON DUPLICATE KEY UPDATE value = VALUES(value);
INSERT INTO translations (lang, source, value) VALUES ('ar', 'தமிழ்நாடு தவ்ஹீத் ஜமாஅத் - கொள்கை', 'جماعة التوحيد في تاميل نادو: عقيدتنا') ON DUPLICATE KEY UPDATE value = VALUES(value);
INSERT INTO translations (lang, source, value) VALUES ('en', 'அல்லாஹ்வின் இறுதி வேதம் திருக்குர்ஆன் மற்றும் முஹம்மது நபி (ஸல்) அவர்களின் தூய நபிவழியே எமது வழிகாட்டி!', 'The Qur\'an, the final revelation of Allah, and the pure Sunnah of the Prophet Muhammad (peace be upon him) are our only guide.') ON DUPLICATE KEY UPDATE value = VALUES(value);
INSERT INTO translations (lang, source, value) VALUES ('ar', 'அல்லாஹ்வின் இறுதி வேதம் திருக்குர்ஆன் மற்றும் முஹம்மது நபி (ஸல்) அவர்களின் தூய நபிவழியே எமது வழிகாட்டி!', 'القرآن الكريم، كتاب الله الخاتم، وسنة النبي محمد ﷺ الصحيحة هما دليلنا الوحيد.') ON DUPLICATE KEY UPDATE value = VALUES(value);
INSERT INTO translations (lang, source, value) VALUES ('en', '<p>திருக்குர்ஆன் மற்றும் ஆதாரப்பூர்வமான நபிமொழிகள் — இவை இரண்டை மட்டுமே மார்க்கத்தின் ஆதாரமாகக் கொண்டு செயல்படும் இயக்கம் தமிழ்நாடு தவ்ஹீத் ஜமாஅத்.</p>', '<p>Tamil Nadu Thowheed Jamath is a movement that takes only the Qur\'an and the authentic hadith as the sources of the religion.</p>') ON DUPLICATE KEY UPDATE value = VALUES(value);
INSERT INTO translations (lang, source, value) VALUES ('ar', '<p>திருக்குர்ஆன் மற்றும் ஆதாரப்பூர்வமான நபிமொழிகள் — இவை இரண்டை மட்டுமே மார்க்கத்தின் ஆதாரமாகக் கொண்டு செயல்படும் இயக்கம் தமிழ்நாடு தவ்ஹீத் ஜமாஅத்.</p>', '<p>جماعة التوحيد في تاميل نادو حركة لا تتخذ مصدرًا للدين إلا القرآن الكريم والأحاديث الصحيحة.</p>') ON DUPLICATE KEY UPDATE value = VALUES(value);
INSERT INTO translations (lang, source, value) VALUES ('en', 'எங்களைப் பற்றி', 'About us') ON DUPLICATE KEY UPDATE value = VALUES(value);
INSERT INTO translations (lang, source, value) VALUES ('ar', 'எங்களைப் பற்றி', 'من نحن') ON DUPLICATE KEY UPDATE value = VALUES(value);
INSERT INTO translations (lang, source, value) VALUES ('en', 'தஞ்சை வடக்கு மாவட்டம்', 'Thanjai North District') ON DUPLICATE KEY UPDATE value = VALUES(value);
INSERT INTO translations (lang, source, value) VALUES ('ar', 'தஞ்சை வடக்கு மாவட்டம்', 'مديرية تنجاي الشمالية') ON DUPLICATE KEY UPDATE value = VALUES(value);
INSERT INTO translations (lang, source, value) VALUES ('en', '<p>தமிழ்நாடு தவ்ஹீத் ஜமாஅத் தஞ்சை வடக்கு மாவட்டம் — ஏகத்துவப் பிரச்சாரம், இரத்ததானம், கல்வி மற்றும் சமூக சேவைப் பணிகளில் ஈடுபட்டு வருகிறது.</p>', '<p>Tamil Nadu Thowheed Jamath, Thanjai North District, works in calling to tawheed, blood donation, education and community service.</p>') ON DUPLICATE KEY UPDATE value = VALUES(value);
INSERT INTO translations (lang, source, value) VALUES ('ar', '<p>தமிழ்நாடு தவ்ஹீத் ஜமாஅத் தஞ்சை வடக்கு மாவட்டம் — ஏகத்துவப் பிரச்சாரம், இரத்ததானம், கல்வி மற்றும் சமூக சேவைப் பணிகளில் ஈடுபட்டு வருகிறது.</p>', '<p>تعمل جماعة التوحيد في تاميل نادو، مديرية تنجاي الشمالية، في الدعوة إلى التوحيد والتبرع بالدم والتعليم وخدمة المجتمع.</p>') ON DUPLICATE KEY UPDATE value = VALUES(value);
INSERT INTO translations (lang, source, value) VALUES ('en', 'தூய ஏகத்துவம் (தவ்ஹீத்)', 'Pure monotheism (Tawheed)') ON DUPLICATE KEY UPDATE value = VALUES(value);
INSERT INTO translations (lang, source, value) VALUES ('ar', 'தூய ஏகத்துவம் (தவ்ஹீத்)', 'التوحيد الخالص') ON DUPLICATE KEY UPDATE value = VALUES(value);
INSERT INTO translations (lang, source, value) VALUES ('en', 'அல்லாஹ் ஒருவனே வணக்கத்திற்குரியவன். அவனுக்கு யாதொரு இணையும் துணையும் இல்லை. இறந்த நல்லடியார்களிடமோ, தர்காக்களிலோ, அவ்லியாக்களிடமோ துஆ (பிரார்த்தனை) செய்வதும், நேர்ச்சை செய்வதும் கொடிய இணைவைத்தல் (ஷிர்க்) ஆகும்.', 'Allah alone deserves worship; He has no partner or associate. Praying to dead saints, at dargahs or to awliya, and making vows to them, is grave shirk (associating partners with Allah).') ON DUPLICATE KEY UPDATE value = VALUES(value);
INSERT INTO translations (lang, source, value) VALUES ('ar', 'அல்லாஹ் ஒருவனே வணக்கத்திற்குரியவன். அவனுக்கு யாதொரு இணையும் துணையும் இல்லை. இறந்த நல்லடியார்களிடமோ, தர்காக்களிலோ, அவ்லியாக்களிடமோ துஆ (பிரார்த்தனை) செய்வதும், நேர்ச்சை செய்வதும் கொடிய இணைவைத்தல் (ஷிர்க்) ஆகும்.', 'الله وحده هو المستحق للعبادة، لا شريك له ولا ند. ودعاء الأموات من الصالحين أو في الأضرحة أو الأولياء، والنذر لهم، شرك أكبر.') ON DUPLICATE KEY UPDATE value = VALUES(value);
INSERT INTO translations (lang, source, value) VALUES ('en', 'தூய நபிவழி (சுன்னா)', 'The pure Sunnah') ON DUPLICATE KEY UPDATE value = VALUES(value);
INSERT INTO translations (lang, source, value) VALUES ('ar', 'தூய நபிவழி (சுன்னா)', 'السنة الخالصة') ON DUPLICATE KEY UPDATE value = VALUES(value);
INSERT INTO translations (lang, source, value) VALUES ('en', 'நபிகள் நாயகம் (ஸல்) அவர்களின் ஆதாரப்பூர்வமான சுன்னாவே மார்க்கத்தின் சட்டமாகும். மார்க்கத்தில் பின்னாளில் சேர்க்கப்பட்ட மீலாது விழா, மௌலிது, கந்தூரி, 3, 7, 40 பாத்திஹா போன்ற அனைத்து பித்அத்துகளும் வழிகேடாகும்.', 'The authentic Sunnah of the Prophet (peace be upon him) is the law of the religion. Every later innovation, such as Milad celebrations, Mawlid, Kandoori and the 3rd, 7th and 40th-day Fatiha, is misguidance.') ON DUPLICATE KEY UPDATE value = VALUES(value);
INSERT INTO translations (lang, source, value) VALUES ('ar', 'நபிகள் நாயகம் (ஸல்) அவர்களின் ஆதாரப்பூர்வமான சுன்னாவே மார்க்கத்தின் சட்டமாகும். மார்க்கத்தில் பின்னாளில் சேர்க்கப்பட்ட மீலாது விழா, மௌலிது, கந்தூரி, 3, 7, 40 பாத்திஹா போன்ற அனைத்து பித்அத்துகளும் வழிகேடாகும்.', 'سنة النبي ﷺ الصحيحة هي شريعة الدين. وكل ما أُحدث لاحقًا من بدع، كالاحتفال بالمولد وقراءة المولد والكندوري وفاتحة اليوم الثالث والسابع والأربعين، ضلالة.') ON DUPLICATE KEY UPDATE value = VALUES(value);
INSERT INTO translations (lang, source, value) VALUES ('en', 'வரதட்சணை மற்றும் ஆடம்பர திருமண ஒழிப்பு', 'Ending dowry and lavish weddings') ON DUPLICATE KEY UPDATE value = VALUES(value);
INSERT INTO translations (lang, source, value) VALUES ('ar', 'வரதட்சணை மற்றும் ஆடம்பர திருமண ஒழிப்பு', 'محاربة المهر المعكوس وإسراف الأعراس') ON DUPLICATE KEY UPDATE value = VALUES(value);
INSERT INTO translations (lang, source, value) VALUES ('en', 'மணமகனிடமிருந்து பணம், நகை, சீர்வரிசை வாங்குவது இஸ்லாத்தில் வன்மையாக கண்டிக்கப்பட்ட ஹராமான குற்றமாகும். மஹர் கொடுத்து, எளிய முறையில் பள்ளிவாசலில் நடத்தப்படும் நபிவழி நிக்காஹ்வை மட்டுமே சமூகம் பின்பற்ற வேண்டும்.', 'Taking money, jewellery or gifts from the bride\'s family is a forbidden (haram) wrong that Islam strongly condemns. The community should follow only the Sunnah nikah: the groom gives the mahr, and the marriage is held simply in the mosque.') ON DUPLICATE KEY UPDATE value = VALUES(value);
INSERT INTO translations (lang, source, value) VALUES ('ar', 'மணமகனிடமிருந்து பணம், நகை, சீர்வரிசை வாங்குவது இஸ்லாத்தில் வன்மையாக கண்டிக்கப்பட்ட ஹராமான குற்றமாகும். மஹர் கொடுத்து, எளிய முறையில் பள்ளிவாசலில் நடத்தப்படும் நபிவழி நிக்காஹ்வை மட்டுமே சமூகம் பின்பற்ற வேண்டும்.', 'أخذ المال أو الذهب أو الهدايا من أهل العروس منكر محرم شديد في الإسلام. وعلى المجتمع أن يتبع النكاح على السنة وحده: يدفع العريس المهر، ويُعقد الزواج ببساطة في المسجد.') ON DUPLICATE KEY UPDATE value = VALUES(value);
INSERT INTO translations (lang, source, value) VALUES ('en', 'மனிதநேய தன்னலமற்ற சேவைகள்', 'Selfless humanitarian service') ON DUPLICATE KEY UPDATE value = VALUES(value);
INSERT INTO translations (lang, source, value) VALUES ('ar', 'மனிதநேய தன்னலமற்ற சேவைகள்', 'الخدمة الإنسانية دون مقابل') ON DUPLICATE KEY UPDATE value = VALUES(value);
INSERT INTO translations (lang, source, value) VALUES ('en', 'மதம், சாதி, மொழி எல்லைகளைக் கடந்து அவசர தேவைக்கு இரத்ததானம் வழங்குதல், இயற்கை பேரிடர் காலங்களில் முன்நின்று களப்பணி ஆற்றுதல் மற்றும் ஆதரவற்ற ஏழை எளியோருக்கு வாழ்வாதார உதவி செய்தல்.', 'Giving blood in emergencies beyond the limits of religion, caste and language; leading field work in natural disasters; and supporting the livelihoods of the poor and helpless.') ON DUPLICATE KEY UPDATE value = VALUES(value);
INSERT INTO translations (lang, source, value) VALUES ('ar', 'மதம், சாதி, மொழி எல்லைகளைக் கடந்து அவசர தேவைக்கு இரத்ததானம் வழங்குதல், இயற்கை பேரிடர் காலங்களில் முன்நின்று களப்பணி ஆற்றுதல் மற்றும் ஆதரவற்ற ஏழை எளியோருக்கு வாழ்வாதார உதவி செய்தல்.', 'التبرع بالدم في الحالات الطارئة دون تمييز في الدين أو الطائفة أو اللغة، والمبادرة بالعمل الميداني في الكوارث الطبيعية، ودعم معيشة الفقراء والمحتاجين.') ON DUPLICATE KEY UPDATE value = VALUES(value);
INSERT INTO translations (lang, source, value) VALUES ('en', 'நளினமான முறையில் சத்தியப் பிரச்சாரம்', 'Calling to the truth with gentleness') ON DUPLICATE KEY UPDATE value = VALUES(value);
INSERT INTO translations (lang, source, value) VALUES ('ar', 'நளினமான முறையில் சத்தியப் பிரச்சாரம்', 'الدعوة إلى الحق بالرفق') ON DUPLICATE KEY UPDATE value = VALUES(value);
INSERT INTO translations (lang, source, value) VALUES ('en', 'அனைத்து மக்களிடமும் இஸ்லாத்தின் தூய கொள்கையை பாசத்துடனும் நளினமான முறையிலும் எடுத்துரைத்தல். பிற மதத்தவரின் நம்பிக்கைகளை பழிக்காமல் ஏகத்துவத்தை தெளிவுபடுத்துதல்.', 'Presenting the pure creed of Islam to all people with affection and gentleness, and explaining tawheed without insulting the beliefs of people of other faiths.') ON DUPLICATE KEY UPDATE value = VALUES(value);
INSERT INTO translations (lang, source, value) VALUES ('ar', 'அனைத்து மக்களிடமும் இஸ்லாத்தின் தூய கொள்கையை பாசத்துடனும் நளினமான முறையிலும் எடுத்துரைத்தல். பிற மதத்தவரின் நம்பிக்கைகளை பழிக்காமல் ஏகத்துவத்தை தெளிவுபடுத்துதல்.', 'عرض عقيدة الإسلام الصافية على جميع الناس بمحبة ورفق، وبيان التوحيد دون الإساءة إلى معتقدات أتباع الأديان الأخرى.') ON DUPLICATE KEY UPDATE value = VALUES(value);
